// =====================================================================
// 3D Game Post Processing Base
// Derived from the proven 3DCRT+ renderer hook and overlay plumbing by
// Twillion. CRT-specific shader math and public CRT controls were removed.
//
// This is intentionally a neutral fullscreen pass. Put the game-specific
// look in applyGameEffect() inside the fragment shader.
// =====================================================================

if (!gdjs._gamePostProcess3D) {
  const vertexShader = `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = vec4(position.xy, 0.0, 1.0);
    }
  `;

  const fragmentShader = `
    precision highp float;
    varying vec2 vUv;

    uniform sampler2D tDiffuse;
    uniform sampler2D tOverlay;
    uniform vec2 dimensions;
    uniform float time;
    uniform float intensity;
    uniform float enOverlay;
    uniform float overlayOpacity;

    vec3 applyGameEffect(vec2 uv, vec3 color) {
      // Game-specific post-processing belongs here.
      // Keep this function neutral until the target game's look is defined.
      return color;
    }

    void main() {
      vec4 source = texture2D(tDiffuse, vUv);
      vec3 effected = applyGameEffect(vUv, source.rgb);

      if (enOverlay > 0.5) {
        vec4 overlay = texture2D(tOverlay, vUv);
        float alpha = clamp(overlay.a * overlayOpacity, 0.0, 1.0);
        effected = mix(effected, overlay.rgb, alpha);
      }

      vec3 finalColor = mix(source.rgb, effected, clamp(intensity, 0.0, 1.0));
      gl_FragColor = vec4(finalColor, source.a);
    }
  `;

  const DEFAULTS = {
    enabled: false,
    intensity: 1,
    overlayLayerName: "",
    enOverlay: false,
    overlayOpacity: 1
  };
  const settings = Object.assign({}, DEFAULTS);

  class GamePostProcessor3D {
    constructor(renderer) {
      this.renderer = renderer;
      this._originalRender = renderer.render;
      this._renderTarget = null;
      this._scene = null;
      this._camera = null;
      this._quad = null;
      this._material = null;
      this._w = 0;
      this._h = 0;
      this._runtimeScene = null;
      this._overlayTexture = null;
      this._pixiRT = null;
      this._pixiRTOwned = false;
      this.targetLayerRenderer = null;

      this._init();
      renderer.__gamePostProcessor3D = this;

      const self = this;
      renderer.render = function(scene, camera) {
        return self._render(scene, camera);
      };
    }

    _init() {
      const THREERef = THREE;
      this._scene = new THREERef.Scene();
      this._camera = new THREERef.Camera();
      this._camera.position.z = 1;

      this._material = new THREERef.ShaderMaterial({
        uniforms: {
          tDiffuse: { value: null },
          tOverlay: { value: null },
          dimensions: { value: new THREERef.Vector2(1, 1) },
          time: { value: 0 },
          intensity: { value: settings.intensity },
          enOverlay: { value: 0 },
          overlayOpacity: { value: settings.overlayOpacity }
        },
        vertexShader,
        fragmentShader,
        depthTest: false,
        depthWrite: false
      });

      this._quad = new THREERef.Mesh(new THREERef.PlaneGeometry(2, 2), this._material);
      this._quad.frustumCulled = false;
      this._scene.add(this._quad);
      this._startTime = (typeof performance !== "undefined" && performance.now) ? performance.now() : Date.now();
    }

    _ensureTarget(w, h) {
      w = Math.max(1, Math.floor(w));
      h = Math.max(1, Math.floor(h));
      if (this._renderTarget && this._w === w && this._h === h) return;

      if (this._renderTarget) this._renderTarget.dispose();
      this._w = w;
      this._h = h;

      const THREERef = THREE;
      this._renderTarget = new THREERef.WebGLRenderTarget(w, h, {
        minFilter: THREERef.LinearFilter,
        magFilter: THREERef.LinearFilter,
        format: THREERef.RGBAFormat,
        depthBuffer: true,
        stencilBuffer: false
      });

      if (THREERef.SRGBColorSpace !== undefined) {
        this._renderTarget.texture.colorSpace = THREERef.SRGBColorSpace;
      } else if (THREERef.sRGBEncoding !== undefined) {
        this._renderTarget.texture.encoding = THREERef.sRGBEncoding;
      }
    }

    _shouldProcess(scene, camera) {
      if (!settings.enabled) return false;
      if (!this.targetLayerRenderer) return true;
      try {
        return camera === this.targetLayerRenderer.getThreeCamera();
      } catch (e) {
        return true;
      }
    }

    _render(scene, camera) {
      const renderer = this.renderer;
      if (!this._shouldProcess(scene, camera)) {
        return this._originalRender.call(renderer, scene, camera);
      }

      const size = new THREE.Vector2();
      renderer.getDrawingBufferSize(size);
      const w = size.x || 1;
      const h = size.y || 1;
      this._ensureTarget(w, h);

      const previousTarget = renderer.getRenderTarget ? renderer.getRenderTarget() : null;
      const previousXr = renderer.xr ? renderer.xr.enabled : false;
      const previousShadowAutoUpdate = renderer.shadowMap ? renderer.shadowMap.autoUpdate : undefined;

      if (renderer.xr) renderer.xr.enabled = false;
      renderer.setRenderTarget(this._renderTarget);
      renderer.clear();
      this._originalRender.call(renderer, scene, camera);

      if (settings.enOverlay && settings.overlayLayerName && this._runtimeScene) {
        this._ensureOverlay(this._runtimeScene, settings.overlayLayerName, w, h);
      } else {
        this._overlayTexture = null;
      }

      this._syncUniforms(w, h);
      renderer.setRenderTarget(previousTarget);
      this._originalRender.call(renderer, this._scene, this._camera);

      if (renderer.xr) renderer.xr.enabled = previousXr;
      if (renderer.shadowMap && previousShadowAutoUpdate !== undefined) {
        renderer.shadowMap.autoUpdate = previousShadowAutoUpdate;
      }
    }

    _syncUniforms(w, h) {
      const u = this._material.uniforms;
      u.tDiffuse.value = this._renderTarget.texture;
      u.dimensions.value.set(w, h);
      u.time.value = (((typeof performance !== "undefined" && performance.now) ? performance.now() : Date.now()) - this._startTime) / 1000;
      u.intensity.value = settings.intensity;
      u.tOverlay.value = this._overlayTexture || null;
      u.enOverlay.value = (settings.enOverlay && this._overlayTexture) ? 1 : 0;
      u.overlayOpacity.value = settings.overlayOpacity;
    }

    _ensureOverlay(runtimeScene, layerName, w, h) {
      try {
        const gr = runtimeScene.getGame().getRenderer();
        const pixi = gr.getPIXIRenderer && gr.getPIXIRenderer();
        const three = this.renderer;
        if (!pixi || !three || typeof PIXI === "undefined") { this._overlayTexture = null; return; }

        const layer = runtimeScene.getLayer(layerName);
        const lr = layer && layer.getRenderer && layer.getRenderer();
        const container = lr && lr._pixiContainer;
        if (!container) { this._overlayTexture = null; return; }

        if (!this._pixiRT) {
          this._pixiRT = PIXI.RenderTexture.create({ width: w, height: h });
        } else if (this._pixiRT.width !== w || this._pixiRT.height !== h) {
          this._pixiRT.resize(w, h);
        }
        this._pixiRTOwned = true;

        try { if (pixi.reset) pixi.reset(); } catch (e) {}

        const pv = container.visible, pr = container.renderable, pa = container.alpha;
        container.visible = true; container.renderable = true; container.alpha = 1;
        pixi.render(container, { renderTexture: this._pixiRT, clear: true });
        container.visible = pv; container.renderable = pr; container.alpha = pa;

        try { if (pixi.renderTexture && pixi.renderTexture.bind) pixi.renderTexture.bind(null); } catch (e) {}
        try { if (pixi.reset) pixi.reset(); } catch (e) {}
        try { if (three.resetState) three.resetState(); } catch (e) {}

        const base = this._pixiRT.baseTexture;
        if (pixi.texture && pixi.texture.bind) pixi.texture.bind(base, 0);
        const glRec = base._glTextures && base._glTextures[pixi.CONTEXT_UID];
        const glHandle = glRec && glRec.texture;
        if (!glHandle) { this._overlayTexture = null; return; }

        if (!this._overlayTexture) {
          const t = new THREE.Texture();
          t.isRenderTargetTexture = true;
          t.minFilter = THREE.LinearFilter;
          t.magFilter = THREE.LinearFilter;
          t.generateMipmaps = false;
          if (THREE.SRGBColorSpace !== undefined) t.colorSpace = THREE.SRGBColorSpace;
          else if (THREE.sRGBEncoding !== undefined) t.encoding = THREE.sRGBEncoding;
          this._overlayTexture = t;
        }
        const props = three.properties && three.properties.get(this._overlayTexture);
        if (props) { props.__webglTexture = glHandle; props.__webglInit = true; }
        else { this._overlayTexture = null; }
      } catch (e) {
        this._overlayTexture = null;
      }
    }

    dispose() {
      try { this.renderer.render = this._originalRender; } catch (e) {}
      delete this.renderer.__gamePostProcessor3D;
      try { if (this._renderTarget) this._renderTarget.dispose(); } catch (e) {}
      try { if (this._material) this._material.dispose(); } catch (e) {}
      try { if (this._quad && this._quad.geometry) this._quad.geometry.dispose(); } catch (e) {}
      try {
        if (this._overlayTexture) {
          const p = this.renderer.properties && this.renderer.properties.get(this._overlayTexture);
          if (p) { p.__webglTexture = undefined; p.__webglInit = false; }
          try { this._overlayTexture.dispose(); } catch (e) {}
          this._overlayTexture = null;
        }
      } catch (e) {}
      try {
        if (this._pixiRT && this._pixiRTOwned) this._pixiRT.destroy(true);
        this._pixiRT = null;
      } catch (e) {}
    }
  }

  const getThreeRenderer = (runtimeScene) => {
    try {
      const gameRenderer = runtimeScene.getGame().getRenderer();
      return gameRenderer && gameRenderer.getThreeRenderer ? gameRenderer.getThreeRenderer() : null;
    } catch (e) {
      return null;
    }
  };

  const getProcessor = (runtimeScene) => {
    const r = getThreeRenderer(runtimeScene);
    return r ? (r.__gamePostProcessor3D || null) : null;
  };

  const ensureProcessor = (runtimeScene) => {
    if (typeof THREE === "undefined") {
      console.warn("GamePostProcess3D: THREE is not available yet.");
      return null;
    }
    const r = getThreeRenderer(runtimeScene);
    if (!r) return null;
    const processor = r.__gamePostProcessor3D || new GamePostProcessor3D(r);
    processor._runtimeScene = runtimeScene;
    return processor;
  };

  const targetLayer = (runtimeScene, processor, layerName) => {
    if (!processor) return;
    if (layerName && runtimeScene.hasLayer && runtimeScene.hasLayer(layerName)) {
      try {
        const layer = runtimeScene.getLayer(layerName);
        const lr = layer && layer.getRenderer && layer.getRenderer();
        processor.targetLayerRenderer = (lr && typeof lr.getThreeCamera === "function") ? lr : null;
      } catch (e) {
        processor.targetLayerRenderer = null;
      }
    } else {
      processor.targetLayerRenderer = null;
    }
  };

  gdjs._gamePostProcess3D = {
    GamePostProcessor3D,
    settings,
    DEFAULTS,

    startEffect(runtimeScene, layer3D) {
      const processor = ensureProcessor(runtimeScene);
      if (!processor) return false;
      settings.enabled = true;
      targetLayer(runtimeScene, processor, layer3D);
      return true;
    },

    stopEffect(runtimeScene) {
      settings.enabled = false;
    },

    isEnabled(runtimeScene) {
      const processor = getProcessor(runtimeScene);
      return !!(processor && settings.enabled);
    },

    tick(runtimeScene, layer3D) {
      const processor = ensureProcessor(runtimeScene);
      if (!processor) return false;
      settings.enabled = true;
      if (layer3D !== undefined) targetLayer(runtimeScene, processor, layer3D);
      return true;
    },

    dispose(runtimeScene) {
      const processor = getProcessor(runtimeScene);
      if (processor) processor.dispose();
    },

    _clamp(v, lo, hi) {
      return Math.min(Math.max(Number(v) || 0, lo), hi);
    },

    setOpacity(runtimeScene, value) {
      settings.intensity = this._clamp(value, 0, 255) / 255;
    },

    getOpacity() {
      return Math.round(settings.intensity * 255);
    },

    renderOverlayLayer(runtimeScene, layerName) {
      settings.overlayLayerName = layerName || "";
      settings.enOverlay = !!settings.overlayLayerName;
      const processor = getProcessor(runtimeScene);
      if (processor) processor._runtimeScene = runtimeScene;
    },

    stopOverlayLayer(runtimeScene) {
      settings.enOverlay = false;
    },

    setOverlayOpacity(runtimeScene, value) {
      settings.overlayOpacity = this._clamp(value, 0, 1);
    }
  };
}

if (!gdjs._gamePostProcess3D) return;
var object = (typeof objects !== "undefined" && objects.length) ? objects[0] : null;
if (!object) return;
var behaviorName = eventsFunctionContext.getBehaviorName("Behavior");
var behavior = object.getBehavior(behaviorName);
if (!behavior) return;
try {
  gdjs._gamePostProcess3D.setOpacity(runtimeScene, behavior._getOpacity());
  gdjs._gamePostProcess3D.tick(runtimeScene, behavior._getTargetLayer());
} catch (e) {
  if (!gdjs._gamePostProcess3D._behaviorErrored) {
    console.error("3D post-processing behavior sync failed:", e);
    gdjs._gamePostProcess3D._behaviorErrored = true;
  }
}
